mapper.select:
/* USE : DayCashSaleBensonMapper.getPayColList */
SELECT tcn.NMCODE_CD AS PAY_CD, DECODE(tcn.NMCODE_CD,'06','VMEM 전자상품권',tcn.NMCODE_NM) AS PAY_NM, tcn.NMCODE_ITEM_1 AS PAY_METHOD FROM TB_CM_NMCODE tcn WHERE tcn.NMCODE_GRP_CD = '024' AND tcn.NMCODE_CD NOT IN ('05', '12') /* 쿠폰은 결제수단이 아닌 할인내역으로 들어가므로 하드코딩으로 결제수단에 나오지 않도록 함. */ ORDER BY tcn.NMCODE_CD
SELECT tcn.NMCODE_CD AS PAY_CD, tcn.NMCODE_NM AS PAY_NM, tcn.NMCODE_ITEM_1 AS PAY_METHOD FROM TB_CM_NMCODE tcn WHERE tcn.NMCODE_GRP_CD = '024' AND tcn.NMCODE_CD NOT IN ('05', '12') /* 쿠폰은 결제수단이 아닌 할인내역으로 들어가므로 하드코딩으로 결제수단에 나오지 않도록 함. */ ORDER BY tcn.NMCODE_CD

/* USE : DayCashSaleBensonMapper.getGuestColList */
SELECT A.NMCODE_CD AS GUEST_CD, NVL(B.NMCODE_NM, '미등록') AS GUEST_NM FROM TB_CM_NMCODE A, TB_HQ_NMCODE B WHERE 1=1 AND A.NMCODE_GRP_CD = '119' AND B.HQ_OFFICE_CD (+)= #{hqOfficeCd} AND B.NMCODE_GRP_CD (+)= A.NMCODE_GRP_CD AND B.NMCODE_CD (+)= A.NMCODE_CD ORDER BY A.NMCODE_CD
SELECT A.NMCODE_CD AS GUEST_CD, NVL(B.NMCODE_NM, '미등록') AS GUEST_NM FROM TB_CM_NMCODE A, TB_MS_STORE_NMCODE B WHERE 1=1 AND A.NMCODE_GRP_CD = '119' AND B.STORE_CD (+)= #{storeCd} AND B.NMCODE_GRP_CD (+)= A.NMCODE_GRP_CD AND B.NMCODE_CD (+)= A.NMCODE_CD ORDER BY A.NMCODE_CD

/* USE : DayCashSaleBensonMapper.getDayCashTotalBensonList */ SELECT tsshp.STORE_CD , tms.STORE_NM , TO_CHAR(TO_DATE(tsshp.SALE_DATE, 'yyyymmdd'), 'yyyy-mm-dd') AS SALE_DATE , TO_CHAR(TO_DATE(tsshp.SALE_DATE, 'YYYYMMDD'), 'DY') AS YOIL , tsshp.TOT_SALE_AMT , tsshp.TOT_DC_AMT , tsshp.REAL_SALE_AMT , tsshp.GA_AMT , tsshp.VAT_AMT , tsshp.TOT_TIP_AMT , tsshp.TOT_ETC_AMT , tsshp.CUP_AMT , tsshp.BILL_CNT , tsshp.BILL_UPRC , tssddp.GEN_REAL_SALE_AMT , DECODE(tsshp.REAL_SALE_AMT, 0, 0, (tssddp.GEN_REAL_SALE_AMT / tsshp.REAL_SALE_AMT)*100) AS GEN_REAL_SALE_RATE , tssddp.DLVR_REAL_SALE_AMT , DECODE(tsshp.REAL_SALE_AMT, 0, 0, (tssddp.DLVR_REAL_SALE_AMT / tsshp.REAL_SALE_AMT)*100) AS DLVR_REAL_SALE_RATE , tssddp.PACK_REAL_SALE_AMT , DECODE(tsshp.REAL_SALE_AMT, 0, 0, (tssddp.PACK_REAL_SALE_AMT / tsshp.REAL_SALE_AMT)*100) AS PACK_REAL_SALE_RATE , NVL(tsshp.PAY${item}, 0) + NVL(tsshpd.PAY0, 0) + NVL(tsshpd.PAY1, 0) + NVL(tsshpd.PAY3, 0) + NVL(tsshpd.PAY4, 0) AS TOT_PAY_AMT , tsshp.PAY${item} AS PAY${item}
, tsshpd.PAY0 -- 현금(매장) , tsshpd.PAY1 -- 현금(CID) , tsshpd.PAY3 -- 현금(배민) , tsshpd.PAY4 -- 현금(요기요) FROM ( SELECT SALE_DATE , STORE_CD , SUM(TOT_SALE_AMT) AS TOT_SALE_AMT , SUM(TOT_DC_AMT) AS TOT_DC_AMT , SUM(REAL_SALE_AMT) AS REAL_SALE_AMT , SUM(REAL_SALE_AMT) - SUM(VAT_AMT) AS GA_AMT , SUM(VAT_AMT) AS VAT_AMT , SUM(TOT_TIP_AMT) AS TOT_TIP_AMT , SUM(TOT_ETC_AMT) AS TOT_ETC_AMT , SUM(CUP_AMT) AS CUP_AMT , SUM(BILL_CNT) AS BILL_CNT , DECODE(SUM(BILL_CNT), 0, 0, ROUND(SUM(REAL_SALE_AMT) / SUM(BILL_CNT))) AS BILL_UPRC , SUM(PAY_AMT_${item}) AS PAY${item}
FROM TB_SL_DAILY_TOTAL tsdt WHERE tsdt.HQ_OFFICE_CD = #{hqOfficeCd}
AND tsdt.STORE_CD IN (${storeCdQuery})
AND ( 'N' = (SELECT NVL(MAX(ENVST_VAL), 'N') FROM TB_HQ_ENVST WHERE HQ_OFFICE_CD = #{hqOfficeCd} AND ENVST_CD = '0001') OR tsdt.STORE_CD IN (SELECT STORE_CD FROM TB_HQ_EMPLOYEE_STORE_V08 WHERE HQ_OFFICE_CD = #{hqOfficeCd} AND EMP_NO = #{empNo}) )
AND tsdt.SALE_DATE BETWEEN #{startDate} AND #{endDate} GROUP BY SALE_DATE, STORE_CD ) tsshp , ( SELECT tssd.SALE_DATE , tssd.STORE_CD , SUM(CASE WHEN tssd.DLVR_ORDER_FG = '1' THEN tssd.REAL_SALE_AMT ELSE 0 END) AS GEN_REAL_SALE_AMT , SUM(CASE WHEN tssd.DLVR_ORDER_FG = '2' THEN tssd.REAL_SALE_AMT ELSE 0 END) AS DLVR_REAL_SALE_AMT , SUM(CASE WHEN tssd.DLVR_ORDER_FG = '3' OR tssd.DLVR_ORDER_FG = '4' THEN tssd.REAL_SALE_AMT ELSE 0 END) AS PACK_REAL_SALE_AMT FROM TB_SL_DAILY_DTL_DLVR tssd WHERE tssd.HQ_OFFICE_CD = #{hqOfficeCd}
AND tssd.STORE_CD IN (${storeCdQuery})
AND ( 'N' = (SELECT NVL(MAX(ENVST_VAL), 'N') FROM TB_HQ_ENVST WHERE HQ_OFFICE_CD = #{hqOfficeCd} AND ENVST_CD = '0001') OR tssd.STORE_CD IN (SELECT STORE_CD FROM TB_HQ_EMPLOYEE_STORE_V08 WHERE HQ_OFFICE_CD = #{hqOfficeCd} AND EMP_NO = #{empNo}) )
AND tssd.SALE_DATE BETWEEN #{startDate} AND #{endDate} GROUP BY tssd.SALE_DATE, tssd.STORE_CD ) tssddp , ( SELECT tsshp.SALE_DATE, tsshp.STORE_CD, SUM(PAY_AMT) - NVL(SUM(CASE tsshd.DLVR_IN_FG WHEN '1' THEN PAY_AMT WHEN '3' THEN PAY_AMT WHEN '4' THEN PAY_AMT END), 0) AS PAY0, SUM(CASE tsshd.DLVR_IN_FG WHEN '1' THEN PAY_AMT END) AS PAY1, SUM(CASE tsshd.DLVR_IN_FG WHEN '3' THEN PAY_AMT END) AS PAY3, SUM(CASE tsshd.DLVR_IN_FG WHEN '4' THEN PAY_AMT END) AS PAY4 FROM TB_SL_SALE_HDR_PAY tsshp LEFT JOIN TB_SL_SALE_HDR_DLVR tsshd ON tsshd.STORE_CD = tsshp.STORE_CD AND tsshd.SALE_DATE = tsshp.SALE_DATE AND tsshd.POS_NO = tsshp.POS_NO AND tsshd.BILL_NO = tsshp.BILL_NO WHERE tsshp.HQ_OFFICE_CD = #{hqOfficeCd} AND tsshp.SALE_DATE BETWEEN #{startDate} AND #{endDate} AND tsshp.PAY_CD = '02'
AND tsshp.STORE_CD IN (${storeCdQuery})
AND ( 'N' = (SELECT NVL(MAX(ENVST_VAL), 'N') FROM TB_HQ_ENVST WHERE HQ_OFFICE_CD = #{hqOfficeCd} AND ENVST_CD = '0001') OR tsshp.STORE_CD IN (SELECT STORE_CD FROM TB_HQ_EMPLOYEE_STORE_V08 WHERE HQ_OFFICE_CD = #{hqOfficeCd} AND EMP_NO = #{empNo}) )
GROUP BY tsshp.SALE_DATE, tsshp.STORE_CD ) tsshpd , TB_MS_STORE tms WHERE tssddp.SALE_DATE (+) = tsshp.SALE_DATE AND tssddp.STORE_CD (+) = tsshp.STORE_CD AND tsshpd.SALE_DATE (+) = tsshp.SALE_DATE AND tsshpd.STORE_CD (+) = tsshp.STORE_CD AND tms.HQ_OFFICE_CD (+) = #{hqOfficeCd} AND tms.STORE_CD (+) = tsshp.STORE_CD ORDER BY tsshp.STORE_CD, tsshp.SALE_DATE DESC
